const empresa = $('GET EMPRESA').item.json;
const hok = $('GET HOK').item.json;

const mensagemOriginal = (hok.msg || '').trim();

function normalize(str = '') {
  return String(str)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function tokenize(str = '') {
  return normalize(str).split(' ').filter(Boolean);
}

function isGreeting(text) {
  const greetings = [
    'oi', 'ola', 'oie', 'opa', 'bom dia', 'boa tarde', 'boa noite',
    'e ai', 'olÃ¡', 'tem alguem ai', 'atendimento'
  ];
  const t = normalize(text);
  return greetings.some(g => t === normalize(g));
}

function lcsLength(ta, tb) {
  const m = ta.length, n = tb.length;
  const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      dp[i][j] = ta[i-1] === tb[j-1]
        ? dp[i-1][j-1] + 1
        : Math.max(dp[i-1][j], dp[i][j-1]);
    }
  }
  return dp[m][n];
}

function lcsScore(a, b) {
  const ta = tokenize(a), tb = tokenize(b);
  if (!ta.length || !tb.length) return 0;
  return lcsLength(ta, tb) / Math.max(ta.length, tb.length);
}

function tokenCoverage(msg, trg) {
  const tm = new Set(tokenize(msg));
  const tt = new Set(tokenize(trg));
  if (!tm.size) return 0;
  let common = 0;
  for (const tok of tm) if (tt.has(tok)) common++;
  return common / tm.size;
}

function scoreIndividual(msg, trg) {
  const mn = normalize(msg);
  const tn = normalize(trg);
  if (!mn || !tn) return 0;
  if (mn === tn) return 1;
  if (mn.length >= 4 && tn.includes(mn)) return 0.92;
  if (tn.length >= 4 && mn.includes(tn)) return 0.95;
  const lcs = lcsScore(mn, tn);
  const cov = tokenCoverage(mn, tn);
  return (lcs * 0.55) + (cov * 0.45);
}

function finalToScore(v) {
  if (v >= 0.92) return 100;
  if (v >= 0.75) return 94;
  if (v >= 0.60) return 88;
  if (v >= 0.48) return 80;
  if (v >= 0.35) return 68;
  if (v >= 0.22) return 52;
  if (v >= 0.10) return 30;
  return 0;
}

function scoreMatch(message, triggers, questionIndex) {
  if (questionIndex === 5) {
    const mn = normalize(message);
    for (const trg of triggers) {
      if (isGreeting(mn) && isGreeting(normalize(trg))) {
        return { score: 98, trigger: trg };
      }
    }
  }

  const msgTokens = new Set(tokenize(normalize(message)));
  const allTriggerTokens = new Set();
  for (const trg of triggers) {
    for (const tok of tokenize(normalize(trg))) allTriggerTokens.add(tok);
  }

  const globalCoverage = msgTokens.size > 0
    ? [...msgTokens].filter(t => allTriggerTokens.has(t)).length / msgTokens.size
    : 0;

  let bestInd = 0;
  let bestTrigger = '';
  for (const trg of triggers) {
    const s = scoreIndividual(message, trg);
    if (s > bestInd) { bestInd = s; bestTrigger = trg; }
  }

  const finalScore = (bestInd * 0.7) + (globalCoverage * 0.3);

  return { score: finalToScore(finalScore), trigger: bestTrigger };
}

const results = [];

for (let i = 1; i <= 30; i++) {
  const raw = (empresa[`q${i}`] || '').trim();
  if (!raw) continue;

  const triggers = raw.split('/').map(s => s.trim()).filter(Boolean);
  const { score, trigger } = scoreMatch(mensagemOriginal, triggers, i);

  results.push({ question: i, score, trigger_match: trigger });
}

results.sort((a, b) => b.score - a.score);

const best = results[0] || { question: null, score: 0, trigger_match: '' };

let confidence = 'low';
if (best.score >= 90) confidence = 'high';
else if (best.score >= 70) confidence = 'medium';

return [
  {
    json: {
      mensagem: mensagemOriginal,
      best_question: best.question,
      best_score: best.score,
      best_trigger: best.trigger_match,
      confidence,
      ranking: results
    }
  }
];

