const normalize = str => (str || '')
  .replace(/\\\\n/g, ' ')
  .replace(/\\n/g, ' ')
  .replace(/\n/g, ' ')
  .replace(/\r/g, '')
  .replace(/\u00A0/g, ' ')
  .replace(/\u200B/g, '')
  .replace(/[^\p{L}\p{N}\p{Emoji} ]/gu, '')
  .replace(/\s+/g, ' ')
  .trim();

const stripForComparison = str =>
  str
    .replace(/https?:\/\/\S+/g, '')
    .replace(/[*_~`]/g, '')
    .replace(/R\$\s?[\d.,]+/g, 'VALOR')
    .toLowerCase();

const tokenize = str =>
  stripForComparison(str)
    .split(/[\s\n\r,.;:!?*_~|()\[\]"'\-\/]+/)
    .filter(t => t.length >= 4);

const jaccard = (a, b) => {
  const sa = new Set(a);
  const sb = new Set(b);
  const inter = [...sa].filter(t => sb.has(t)).length;
  const union = new Set([...sa, ...sb]).size;
  return union === 0 ? 0 : inter / union;
};

const containment = (tokensA, tokensB) => {
  const smaller = tokensA.length <= tokensB.length ? tokensA : tokensB;
  const larger  = tokensA.length >  tokensB.length ? tokensA : tokensB;
  const setLarger = new Set(larger);
  const hits = smaller.filter(t => setLarger.has(t)).length;
  return smaller.length === 0 ? 0 : hits / smaller.length;
};

const JACCARD_THRESHOLD     = 0.72;
const CONTAINMENT_THRESHOLD = 0.85;

